[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-internal",
  "answer": "75세 7제 복용 여성의 낙상에서 즉시 배제할 약물 유발 요인은 (1) 기립성 저혈압(항고혈압제·이뇨제·α차단제·TCA), (2) 진정·인지 저하(벤조디아제핀·Z-drug·진정 항우울제·오피오이드·1세대 항히스타민), (3) 저혈당(인슐린·설폰요소제), (4) 전해질 이상(이뇨제 유발 저나트륨·저칼륨, SSRI/SNRI 유발 저나트륨)입니다. 다만 복용 약물 성분·용량·활력징후·낙상 경위가 확인되지 않아 실제 우선순위는 성분 확인 후에 확정되며, 본 소견의 confidence는 information 부족으로 하향 표기됩니다.",
  "red_flag": {
    "present": false,
    "items": [
      { "id": "I8", "evidence": "활력징후(혈압·맥박·산소포화도) 미제공 — 기립성 저혈압 확인 불가", "basis": "history" }
    ]
  },
  "hypotheses": [
    {
      "name": "약물 유발 기립성 저혈압",
      "icd10": "I95.1",
      "must_not_miss": true,
      "probability_band": "high",
      "supports": [
        { "text": "항고혈압제 다수 복용(가정) — 75세, 다약제", "basis": "history" },
        { "text": "고혈압 기저질환", "basis": "history" }
      ],
      "against": [
        { "text": "기립 시 혈압 변화 측정값 없음 — 기립성 저혈압 확인·배제 불가", "basis": "measurement" }
      ]
    },
    {
      "name": "약물 유발 진정·인지 저하(벤조디아제핀·Z-drug·진정 항우울제·오피오이드·1세대 항히스타민)",
      "icd10": "T43.5 / T42.4 (약물 부작용, 원인 약물에 따름)",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "항우울제(SSRI/SNRI 등) 복용(가정) — 일부 항우울제는 진정 작용", "basis": "history" },
        { "text": "우울 기저질환 — 수면제·벤조디아제핀 병용 가능성 있으나 미확인", "basis": "history" }
      ],
      "against": [
        { "text": "7제 중 구체 성분 미상 — 진정 작용 약물 포함 여부 확인 안 됨", "basis": "history" }
      ]
    },
    {
      "name": "약물 유발 저혈당",
      "icd10": "E16.2 / T38.3 (약물 유발)",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "당뇨 기저질환 + 당뇨약 복용(가정)", "basis": "history" },
        { "text": "75세 — 저혈당 인지 저하 및 약물 대사 저하", "basis": "history" }
      ],
      "against": [
        { "text": "낙상 시 혈당 측정값 없음", "basis": "measurement" },
        { "text": "당뇨약 계열(설폰요소제·인슐린 등 저혈당 위험군 여부) 미확인", "basis": "history" }
      ]
    },
    {
      "name": "약물 유발 전해질 이상(저나트륨·저칼륨)",
      "icd10": "E87.1 / E87.6",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "이뇨제 복용 가능성(항고혈압제 다수 가정) — 저나트륨·저칼륨 위험", "basis": "history" },
        { "text": "SSRI/SNRI(가정) — SIADH를 통한 저나트륨 위험, 특히 고령·여성", "basis": "guideline" }
      ],
      "against": [
        { "text": "전해질 검사값 없음 — 확인·배제 불가", "basis": "measurement" }
      ]
    },
    {
      "name": "비스포스포네이트 관련 (저칼슘혈증·근골격 증상 등)",
      "icd10": "E83.5 / M81.0 관련",
      "must_not_miss": false,
      "probability_band": "low",
      "supports": [
        { "text": "골다공증약(비스포스포네이트 등) 복용(가정)", "basis": "history" }
      ],
      "against": [
        { "text": "낙상과의 인과는 통상 약함(골절 위험 증가와는 별개 경로)", "basis": "guideline" }
      ]
    }
  ],
  "missing_info": [
    "복용 중인 7제의 성분명·용량·복용 시각(특히 항고혈압제 종류와 이뇨제 포함 여부, 당뇨약 계열, 항우울제 성분, 수면제·벤조디아제핀·항히스타민 병용 여부)"
  ],
  "suggested_tests": [
    { "name": "기립성(체위성) 혈압 측정 — 누운 자세 및 기립 1·3분 혈압·맥박", "purpose": "약물 유발 기립성 저혈압 확인", "urgency": "now", "basis": "guideline" },
    { "name": "모세혈관 혈당(낙상 당시 및 공복/저혈당 의심 시)", "purpose": "저혈당 확인", "urgency": "now", "basis": "guideline" },
    { "name": "혈청 전해질(Na, K, Ca, Mg) 및 신기능(BUN/Cr, eGFR)", "purpose": "이뇨제·SSRI/SNRI 유발 저나트륨, 신기능 저하 확인", "urgency": "now", "basis": "guideline" },
    { "name": "심전도", "purpose": "QT 연장·부정맥·서맥 등 낙상 기여 가능성 확인", "urgency": "24h", "basis": "guideline" },
    { "name": "복용 약물 전체 검토(약사·의사, 다약제 상호작용·감량 후보 확인)", "purpose": "감량·중단·대체 가능 약물 선별", "urgency": "24h", "basis": "guideline" }
  ],
  "suggested_treatments": [
    {
      "kind": "referral",
      "description": "복용 약물 성분 확인 후 의사·약사와 함께 감량·중단·대체를 단계적으로 검토. 일반적 우선순위: (1) 저혈당·기립성 저혈압·진정·전해질 위험이 큰 약물부터, (2) 동일 적응증 내에서 부작용 적은 대체약 검토, (3) 한 번에 하나씩 변경하고 변경 후 재평가. 개별 약물의 감량·중단 여부·용량은 반드시 처방의(또는 약사) 확인 하에 결정.",
      "basis": "guideline"
    },
    {
      "kind": "self_care",
      "description": "기립 시 천천히 일어나기, 야간 조명·미끄럼 방지, 낙상 재발 시 즉시 재평가. 어지럼·실신·호흡곤란·흉통·의식 변화 시 즉시 응급 평가.",
      "basis": "guideline"
    }
  ],
  "handoff": {
    "better_specialty": "kdoctor-family",
    "reason": "다약제 조정·낙상 예방·만성질환 연속 관리는 가정의학과가 일차 적합. 약물 감량·대체 실행은 처방의(내과·가정의학과·정신건강의학과 등) 확인 필요. 낙상 평가·골절 위험 관리는 필요 시 kdoctor-orthopedics와 협진 권장."
  },
  "confidence": { "clinical": 3, "information": 1 },
  "warnings": [
    "복용 약물 7제의 성분·용량·복용 시각이 제공되지 않아 실제 위험 순위는 성분 확인 후 달라질 수 있음.",
    "낙상 경위·횟수·활력징후·혈당·전해질 값이 없어 약물 유발 요인을 확정할 수 없음 — 모두 '가능성' 수준.",
    "본 소견은 진단을 확정하지 않으며, 감량·중단·대체는 반드시 처방의(또는 약사) 확인 하에 결정.",
    "다약제 복용자로 상호작용 가능성이 있으며, 약사·의사 검토가 필요함.",
    "[규칙 C6] 고령(75세)·다약제·우울 병력으로 특수 집단 규칙 적용 — 해당 정보 일부 미확인으로 confidence 하향 표기됨."
  ]
}
[/SPECIALIST_FINDING]

자기 점검: C1(해당 없음 — 활력징후 미제공으로 I8은 red_flag 항목에 기록), C2(모든 항목 근거 유형 표기), C3("가능성/시사" 표현만 사용, 확정 표현 없음), C4(용량 수치 서술 없음 — 처방의 확인으로만 기재). 총괄 부록 R 계열 위험 신호 확인을 위해 활력징후·혈당·전해질 재확인이 필요합니다.
